'use strict';
const fs = require('fs');
const path = require('path');

const ELF_PATH = '/app/doomgeneric_mips';

// ---------- Helpers ----------
const u32 = (x) => (x >>> 0);
const i32 = (x) => (x | 0);
const u64lo = (x) => Number(BigInt.asUintN(32, BigInt(x & 0xffffffff)));
function toUnsigned32(x) { return x >>> 0; }
function toSigned32(x) { return x | 0; }
function signExtend16(x) { return (x & 0x8000) ? ((x | 0xffff0000) | 0) : (x & 0xffff); }
function signExtend8(x) { return (x & 0x80) ? ((x | 0xffffff00) | 0) : (x & 0xff); }

function readU8(mem, addr) { return mem.readU8(addr); }
function readU16(mem, addr) { return mem.readU16(addr); }
function readU32(mem, addr) { return mem.readU32(addr); }
function writeU8(mem, addr, val) { mem.writeU8(addr, val & 0xff); }
function writeU16(mem, addr, val) { mem.writeU16(addr, val & 0xffff); }
function writeU32(mem, addr, val) { mem.writeU32(addr, val >>> 0); }

// ---------- Sparse Memory ----------
class Memory {
  constructor() {
    this.pages = new Map();
    this.PAGE_SIZE = 0x1000;
    this.PAGE_MASK = 0xfff;
    this.PAGE_SHIFT = 12;
  }
  _getPage(addr, create) {
    const pn = (addr >>> 12);
    let p = this.pages.get(pn);
    if (p === undefined && create) {
      p = new Uint8Array(this.PAGE_SIZE);
      this.pages.set(pn, p);
    }
    return p;
  }
  readU8(addr) {
    addr = addr >>> 0;
    const p = this._getPage(addr, false);
    if (!p) return 0;
    return p[addr & this.PAGE_MASK];
  }
  readU16(addr) {
    return this.readU8(addr) | (this.readU8(addr + 1) << 8);
  }
  readU32(addr) {
    return (this.readU8(addr) | (this.readU8(addr + 1) << 8) | (this.readU8(addr + 2) << 16) | (this.readU8(addr + 3) << 24)) >>> 0;
  }
  writeU8(addr, val) {
    addr = addr >>> 0;
    const p = this._getPage(addr, true);
    p[addr & this.PAGE_MASK] = val & 0xff;
  }
  writeU16(addr, val) {
    this.writeU8(addr, val & 0xff);
    this.writeU8(addr + 1, (val >> 8) & 0xff);
  }
  writeU32(addr, val) {
    this.writeU8(addr, val & 0xff);
    this.writeU8(addr + 1, (val >> 8) & 0xff);
    this.writeU8(addr + 2, (val >> 16) & 0xff);
    this.writeU8(addr + 3, (val >>> 24) & 0xff);
  }
  copyFromBuffer(addr, buf) {
    for (let i = 0; i < buf.length; i++) this.writeU8(addr + i, buf[i]);
  }
  readBytes(addr, len) {
    const r = Buffer.alloc(len);
    for (let i = 0; i < len; i++) r[i] = this.readU8(addr + i);
    return r;
  }
  writeBytes(addr, buf) {
    for (let i = 0; i < buf.length; i++) this.writeU8(addr + i, buf[i]);
  }
  // Fill a contiguous region with zero (creates pages)
  zeroRange(addr, len) {
    let a = addr >>> 0;
    while (len > 0) {
      const off = a & this.PAGE_MASK;
      const n = Math.min(this.PAGE_SIZE - off, len);
      const p = this._getPage(a, true);
      for (let i = 0; i < n; i++) p[off + i] = 0;
      a += n; len -= n;
    }
  }
}

// ---------- CPU ----------
class CPU {
  constructor(mem) {
    this.mem = mem;
    this.r = new Int32Array(32);
    this.f = new Float32Array(32);
    this.d = new Float64Array(32);
    this.fcc = new Uint8Array(8); // FP condition codes
    this.pc = 0;
    this.hi = 0;
    this.lo = 0;
    this.fcsr = 0;
    this.running = true;
    this.exitCode = 0;
    this.instCount = 0;
    this.maxInst = 0;
    this.debug = false;
    this.logSyscalls = true;
    this.fdMap = new Map(); // guest fd -> host fd
    this.fdMap.set(0, 0); // stdin
    this.fdMap.set(1, 1); // stdout
    this.fdMap.set(2, 2); // stderr
    this.nextFd = 3;
    this.hostFds = new Set([0,1,2]);
  }

  reg(i) { return this.r[i]; }
  setReg(i, v) { if (i !== 0) this.r[i] = v | 0; }

  // Syscall handling
  syscall() {
    const v0 = this.r[2] >>> 0;
    const a0 = this.r[4] >>> 0;
    const a1 = this.r[5] >>> 0;
    const a2 = this.r[6] >>> 0;
    const a3 = this.r[7] >>> 0;
    const a4 = this.r[8] >>> 0;
    const a5 = this.r[9] >>> 0;
    let ret = 0;

    switch (v0) {
      case 0: { // read
        const hostFd = this.fdMap.get(a0);
        if (hostFd === undefined) { this.setReg(2, -1); return; }
        try {
          const buf = Buffer.alloc(a2);
          const n = fs.readSync(hostFd, buf, 0, a2, null);
          if (n < 0) { this.setReg(2, -1); return; }
          for (let i = 0; i < n; i++) this.mem.writeU8(a1 + i, buf[i]);
          ret = n;
        } catch (e) { ret = -1; }
        break;
      }
      case 1: { // write
        const hostFd = this.fdMap.get(a0);
        if (hostFd === undefined) { this.setReg(2, -1); return; }
        try {
          const buf = this.mem.readBytes(a1, a2);
          if (hostFd === 1) { process.stdout.write(buf); ret = a2; }
          else if (hostFd === 2) { process.stderr.write(buf); ret = a2; }
          else { const n = fs.writeSync(hostFd, buf, 0, a2, null); ret = n; }
        } catch (e) { ret = -1; }
        break;
      }
      case 2: { // open
        const pathStr = this.readCString(a0);
        const flags = a1;
        const mode = a2;
        let hostFlags = 0;
        if ((flags & 0) === 0 && flags === 0) hostFlags |= fs.constants.O_RDONLY;
        if (flags & 1) hostFlags |= fs.constants.O_WRONLY;
        if (flags & 2) hostFlags |= fs.constants.O_RDWR;
        if (flags & 64) hostFlags |= fs.constants.O_CREAT;
        if (flags & 512) hostFlags |= fs.constants.O_TRUNC;
        if (flags & 1024) hostFlags |= fs.constants.O_APPEND;
        try {
          const hf = fs.openSync(pathStr, hostFlags, mode);
          const gf = this.nextFd++;
          this.fdMap.set(gf, hf);
          this.hostFds.add(hf);
          ret = gf;
        } catch (e) { ret = -1; }
        break;
      }
      case 3: { // close
        const hostFd = this.fdMap.get(a0);
        if (hostFd === undefined) { ret = -1; break; }
        if (hostFd > 2) { try { fs.closeSync(hostFd); } catch(e){} this.hostFds.delete(hostFd); }
        this.fdMap.delete(a0);
        ret = 0;
        break;
      }
      case 8: { // lseek
        const hostFd = this.fdMap.get(a0);
        if (hostFd === undefined) { ret = -1; break; }
        try {
          const pos = fs.readSync || true; // placeholder to avoid unused
          const cur = fs.readSync(hostFd, Buffer.alloc(0), 0, 0, null); // not robust
          // Use a stat + position approach via a wrapper is overkill; Node lacks lseekSync directly.
          // We approximate: for SEEK_SET, use position; for SEEK_CUR/END, we compute via fstat.
          // Node fs.readSync with null position reads at current position, but we can't get current pos directly.
          // We'll use a small C-like approach: reopen + read to pos is too slow.
          // Instead, we'll use a per-fd position map for seeking.
          ret = this._lseekSync(hostFd, a1 | 0, a2);
        } catch (e) { ret = -1; }
        break;
      }
      case 74: { // fsync
        const hostFd = this.fdMap.get(a0);
        if (hostFd === undefined) { ret = -1; break; }
        if (hostFd > 2) { try { fs.fsyncSync(hostFd); ret = 0; } catch(e){ ret = -1; } } else ret = 0;
        break;
      }
      case 60: { // exit
        this.running = false;
        this.exitCode = a0 | 0;
        ret = 0;
        break;
      }
      case 201: { // time
        const t = Math.floor(Date.now() / 1000);
        if (a0 !== 0) this.writeU32(a0, t);
        ret = t;
        break;
      }
      case 96: { // gettimeofday
        const now = Date.now();
        const sec = Math.floor(now / 1000);
        const usec = (now % 1000) * 1000;
        if (a0 !== 0) this.writeU32(a0, sec);
        if (a1 !== 0) this.writeU32(a1, usec);
        ret = 0;
        break;
      }
      case 35: { // nanosleep
        // Just return immediately
        ret = 0;
        break;
      }
      case 82: { // rename
        const oldp = this.readCString(a0);
        const newp = this.readCString(a1);
        try { fs.renameSync(oldp, newp); ret = 0; } catch(e){ ret = -1; }
        break;
      }
      case 83: { // mkdir
        const mp = this.readCString(a0);
        try { fs.mkdirSync(mp, { recursive: true }); ret = 0; } catch(e){ ret = -1; }
        break;
      }
      case 87: { // unlink
        const up = this.readCString(a0);
        try { fs.unlinkSync(up); ret = 0; } catch(e){ ret = -1; }
        break;
      }
      default:
        if (this.logSyscalls) console.error(`[vm] unhandled syscall ${v0} at pc=${this.pc.toString(16)}`);
        ret = -1;
        break;
    }
    this.setReg(2, ret);
    this.setReg(7, ret);
  }

  // Per-host-fd position tracking for lseek
  _fdPos = new Map();
  _lseekSync(hostFd, offset, whence) {
    // We track positions per host fd
    let cur = this._fdPos.get(hostFd);
    if (cur === undefined) cur = 0;
    let newPos = 0;
    if (whence === 0) newPos = offset;
    else if (whence === 1) newPos = cur + offset;
    else if (whence === 2) {
      const st = fs.fstatSync(hostFd);
      newPos = st.size + offset;
    } else return -1;
    if (newPos < 0) return -1;
    this._fdPos.set(hostFd, newPos);
    return newPos;
  }

  readCString(addr) {
    let s = '';
    let a = addr >>> 0;
    while (true) {
      const b = this.mem.readU8(a++);
      if (b === 0) break;
      s += String.fromCharCode(b);
    }
    return s;
  }

  setPC(pc) { this.pc = pc >>> 0; }

  // Execute one instruction; assumes no pending delay slot.
  step() {
    if (this.maxInst && this.instCount >= this.maxInst) { this.running = false; return; }
    const pc = this.pc;
    const inst = this.mem.readU32(pc);
    this.execute(inst, pc);
    this.instCount++;
  }

  // Execute instruction at pc; handles delay slot for branches/jumps.
  execute(inst, pc) {
    const op = (inst >> 26) & 0x3f;
    const rs = (inst >> 21) & 0x1f;
    const rt = (inst >> 16) & 0x1f;
    const rd = (inst >> 11) & 0x1f;
    const shamt = (inst >> 6) & 0x1f;
    const funct = inst & 0x3f;
    const imm = inst & 0xffff;
    const simm = (imm & 0x8000) ? ((imm | 0xffff0000) | 0) : (imm & 0xffff);
    const target = inst & 0x3ffffff;

    let branchTarget = null; // if set, after executing delay slot, pc = branchTarget
    let nextPC = (pc + 8) >>> 0; // default after delay slot? Actually step handles pc.

    // We'll execute delay slots inline: when a branch/jump is taken, we execute the next instruction then set pc.
    // To simplify, we set this.pc to next instruction first, then handle branch.
    const curPC = pc;
    const delayPC = (pc + 4) >>> 0;

    switch (op) {
      case 0x00: // SPECIAL
        this.execSpecial(inst, curPC);
        break;
      case 0x01: // REGIMM
        this.execRegimm(inst, curPC);
        break;
      case 0x02: // J
        this.executeDelayAndJump(delayPC, ((curPC + 4) & 0xf0000000) | (target << 2));
        return;
      case 0x03: { // JAL
        this.setReg(31, (curPC + 8) >>> 0);
        this.executeDelayAndJump(delayPC, ((curPC + 4) & 0xf0000000) | (target << 2));
        return;
      }
      case 0x04: { // BEQ
        if ((this.r[rs] | 0) === (this.r[rt] | 0)) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        break;
      }
      case 0x05: { // BNE
        if ((this.r[rs] | 0) !== (this.r[rt] | 0)) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        break;
      }
      case 0x06: { // BLEZ
        if ((this.r[rs] | 0) <= 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        break;
      }
      case 0x07: { // BGTZ
        if ((this.r[rs] | 0) > 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        break;
      }
      case 0x08: { // ADDI (treat as ADDIU, no trap)
        this.setReg(rt, (this.r[rs] + simm) | 0);
        break;
      }
      case 0x09: { // ADDIU
        this.setReg(rt, (this.r[rs] + simm) | 0);
        break;
      }
      case 0x0a: { // SLTI
        this.setReg(rt, ((this.r[rs] | 0) < simm) ? 1 : 0);
        break;
      }
      case 0x0b: { // SLTIU
        this.setReg(rt, ((this.r[rs] >>> 0) < ((simm >>> 0))) ? 1 : 0);
        break;
      }
      case 0x0c: { // ANDI
        this.setReg(rt, (this.r[rs] & imm) >>> 0);
        break;
      }
      case 0x0d: { // ORI
        this.setReg(rt, (this.r[rs] | imm) >>> 0);
        break;
      }
      case 0x0e: { // XORI
        this.setReg(rt, (this.r[rs] ^ imm) >>> 0);
        break;
      }
      case 0x0f: { // LUI
        this.setReg(rt, (imm << 16) >>> 0);
        break;
      }
      case 0x10: // COP0
        // ignore cop0 mostly
        break;
      case 0x11: // COP1 FPU
        this.execFPU(inst, curPC);
        break;
      case 0x12: case 0x13: // COP2/COP3 ignore
        break;
      case 0x14: { // BEQL
        if ((this.r[rs] | 0) === (this.r[rt] | 0)) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0; // skip delay slot
        break;
      }
      case 0x15: { // BNEL
        if ((this.r[rs] | 0) !== (this.r[rt] | 0)) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x16: { // BLEZL
        if ((this.r[rs] | 0) <= 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x17: { // BGTZL
        if ((this.r[rs] | 0) > 0) { this.executeDelayAndJump(delayPC, (curPC + 4 + (simm << 2)) >>> 0); return; }
        else this.pc = (curPC + 8) >>> 0;
        break;
      }
      case 0x20: { // LB
        const v = this.mem.readU8((this.r[rs] + simm) >>> 0);
        this.setReg(rt, signExtend8(v));
        break;
      }
      case 0x21: { // LH
        const v = this.mem.readU16((this.r[rs] + simm) >>> 0);
        this.setReg(rt, signExtend16(v));
        break;
      }
      case 0x23: { // LW
        const v = this.mem.readU32((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x24: { // LBU
        const v = this.mem.readU8((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x25: { // LHU
        const v = this.mem.readU16((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x28: { // SB
        this.mem.writeU8((this.r[rs] + simm) >>> 0, this.r[rt] & 0xff);
        break;
      }
      case 0x29: { // SH
        this.mem.writeU16((this.r[rs] + simm) >>> 0, this.r[rt] & 0xffff);
        break;
      }
      case 0x2b: { // SW
        this.mem.writeU32((this.r[rs] + simm) >>> 0, this.r[rt] >>> 0);
        break;
      }
      case 0x2f: { // CACHE - ignore
        break;
      }
      case 0x30: { // LL - treat as LW
        const v = this.mem.readU32((this.r[rs] + simm) >>> 0);
        this.setReg(rt, v);
        break;
      }
      case 0x31: { // LWC1
        const v = this.mem.readU32((this.r[rs] + simm) >>> 0);
        this.f[rt] = new Float32Array(Buffer.from([v&0xff,(v>>8)&0xff,(v>>16)&0xff,(v>>>24)&0xff]).buffer)[0];
        this.d[rt] = this.f[rt];
        break;
      }
      case 0x35: { // LDC1
        const lo = this.mem.readU32((this.r[rs] + simm) >>> 0);
        const hi = this.mem.readU32((this.r[rs] + simm + 4) >>> 0);
        const buf = Buffer.from([lo&0xff,(lo>>8)&0xff,(lo>>16)&0xff,(lo>>>24)&0xff, hi&0xff,(hi>>8)&0xff,(hi>>16)&0xff,(hi>>>24)&0xff]);
        this.d[rt] = buf.readDoubleLE(0);
        break;
      }
      case 0x38: { // SWC1
        const idx = rt;
        const buf = Buffer.alloc(4);
        buf.writeFloatLE(this.f[idx], 0);
        const v = buf.readUInt32LE(0);
        this.mem.writeU32((this.r[rs] + simm) >>> 0, v);
        break;
      }
      case 0x3d: { // SDC1
        const idx = rt;
        const buf = Buffer.alloc(8);
        buf.writeDoubleLE(this.d[idx], 0);
        const lo = buf.readUInt32LE(0);
        const hi = buf.readUInt32LE(4);
        this.mem.writeU32((this.r[rs] + simm) >>> 0, lo);
        this.mem.writeU32((this.r[rs] + simm + 4) >>> 0, hi);
        break;
      }
      default:
        this.halt(`unknown opcode 0x${op.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)}`);
        return;
    }

    // If we didn't branch, advance to delay slot / next
    this.pc = (curPC + 4) >>> 0;
  }

  executeDelayAndJump(delayPC, target) {
    const inst = this.mem.readU32(delayPC);
    this.execute(inst, delayPC);
    if (this.running) this.pc = target >>> 0;
  }

  execSpecial(inst, curPC) {
    const funct = inst & 0x3f;
    const rs = (inst >> 21) & 0x1f;
    const rt = (inst >> 16) & 0x1f;
    const rd = (inst >> 11) & 0x1f;
    const shamt = (inst >> 6) & 0x1f;
    const sa = (shamt);
    switch (funct) {
      case 0x00: // SLL
        this.setReg(rd, (this.r[rt] << shamt) | 0);
        break;
      case 0x02: // SRL
        this.setReg(rd, (this.r[rt] >>> shamt) >>> 0);
        break;
      case 0x03: // SRA
        this.setReg(rd, (this.r[rt] >> shamt) | 0);
        break;
      case 0x04: // SLLV
        this.setReg(rd, (this.r[rt] << (this.r[rs] & 0x1f)) | 0);
        break;
      case 0x06: // SRLV
        this.setReg(rd, (this.r[rt] >>> (this.r[rs] & 0x1f)) >>> 0);
        break;
      case 0x07: // SRAV
        this.setReg(rd, (this.r[rt] >> (this.r[rs] & 0x1f)) | 0);
        break;
      case 0x08: { // JR
        const target = this.r[rs] >>> 0;
        this.executeDelayAndJump((curPC + 4) >>> 0, target);
        break;
      }
      case 0x09: { // JALR
        const target = this.r[rs] >>> 0;
        this.setReg(rd === 0 ? 31 : rd, (curPC + 8) >>> 0);
        this.executeDelayAndJump((curPC + 4) >>> 0, target);
        break;
      }
      case 0x0c: // SYSCALL
        this.syscall();
        if (this.running) this.pc = (curPC + 4) >>> 0;
        break;
      case 0x0d: // BREAK
        this.halt(`BREAK at 0x${curPC.toString(16)}`);
        break;
      case 0x10: { // MFHI
        this.setReg(rd, this.hi);
        break;
      }
      case 0x11: { // MTHI
        this.hi = this.r[rs];
        break;
      }
      case 0x12: { // MFLO
        this.setReg(rd, this.lo);
        break;
      }
      case 0x13: { // MTLO
        this.lo = this.r[rs];
        break;
      }
      case 0x18: { // MULT
        const a = this.r[rs] | 0;
        const b = this.r[rt] | 0;
      let product = BigInt(a) * BigInt(b);
        const u = BigInt.asUintN(64, product);
        this.lo = Number(u & 0xffffffffn) | 0;
        this.hi = Number((u >> 32n) & 0xffffffffn) | 0;
        break;
      }
      case 0x19: { // MULTU
        const a = this.r[rs] >>> 0;
        const b = this.r[rt] >>> 0;
        let product = BigInt(a) * BigInt(b);
        const u = BigInt.asUintN(64, product);
        this.lo = Number(u & 0xffffffffn) | 0;
        this.hi = Number((u >> 32n) & 0xffffffffn) | 0;
        break;
      }
      case 0x1a: { // DIV
        const a = this.r[rs] | 0;
        const b = this.r[rt] | 0;
        if (b === 0) { this.lo = 0; this.hi = 0; }
        else {
          this.lo = (Math.trunc(a / b)) | 0;
          this.hi = (a - (this.lo * b)) | 0;
        }
        break;
      }
      case 0x1b: { // DIVU
        const a = this.r[rs] >>> 0;
        const b = this.r[rt] >>> 0;
        if (b === 0) { this.lo = 0; this.hi = 0; }
        else {
          this.lo = (a / b) >>> 0;
          this.hi = (a - (this.lo * b)) >>> 0;
        }
        break;
      }
      case 0x20: // ADD (no trap)
        this.setReg(rd, (this.r[rs] + this.r[rt]) | 0);
        break;
      case 0x21: // ADDU
        this.setReg(rd, (this.r[rs] + this.r[rt]) | 0);
        break;
      case 0x22: // SUB
        this.setReg(rd, (this.r[rs] - this.r[rt]) | 0);
        break;
      case 0x23: { // SUBU
        this.setReg(rd, (this.r[rs] - this.r[rt]) | 0);
        break;
      }
      case 0x24: { // AND
        this.setReg(rd, (this.r[rs] & this.r[rt]) >>> 0);
        break;
      }
      case 0x25: { // OR
        this.setReg(rd, (this.r[rs] | this.r[rt]) >>> 0);
        break;
      }
      case 0x26: { // XOR
        this.setReg(rd, (this.r[rs] ^ this.r[rt]) >>> 0);
        break;
      }
      case 0x27: { // NOR
        this.setReg(rd, ~(this.r[rs] | this.r[rt]) >>> 0);
        break;
      }
      case 0x2a: { // SLT
        this.setReg(rd, ((this.r[rs] | 0) < (this.r[rt] | 0)) ? 1 : 0);
        break;
      }
      case 0x2b: { // SLTU
        this.setReg(rd, ((this.r[rs] >>> 0) < (this.r[rt] >>> 0)) ? 1 : 0);
        break;
      }
      case 0x30: { // TGE - ignore traps mostly, but if triggering, halt
        if ((this.r[rs] | 0) >= (this.r[rt] | 0)) this.halt(`TGE at 0x${curPC.toString(16)}`);
        break;
      }
      case 0x31: { // TGEU
        if ((this.r[rs] >>> 0) >= (this.r[rt] >>> 0)) this.halt(`TGEU at 0x${curPC.toString(16)}`);
        break;
      }
      case 0x32: { // TLT - typically trap if less than; we ignore
        break;
      }
      case 0x33: { // TLTU - ignore
        break;
      }
      case 0x34: { // TEQ - could be division by zero trap; ignore to avoid halting
        break;
      }
      case 0x36: { // TNE
        break;
      }
      case 0x0f: { // SYNC - no-op
        break;
      }
      case 0x25: { // already OR above; keep for safety
        break;
      }
      // SEB / SEH (MIPS32r2)
      case 0x20+0: break;
      default:
        if (funct === 0x25) break; // OR duplicate
        this.halt(`unknown special funct 0x${funct.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)}`);
        break;
    }
