    const fdReal = (inst >> 6) & 0x1f;
    const fsReal = (inst >> 11) & 0x1f;
    const ftReal = (inst >> 16) & 0x1f;

    if ((inst & (1<<25)) || fmt !== 0 && fmt !== 0x10 && fmt !== 0x11 && fmt !== 0x14 && fmt !== 0x15) {
      // Some COP1 instructions have fmt=0 for MFC1 etc
    }

