    // Actually op=0x11 covers all COP1. We already handled LWC1/LDC1/SWC1/SDC1 in main switch.
    // Here handle MFC1, CFC1, MTC1, CTC1, BC, and arithmetic.
    const sub = (inst >> 21) & 0x1f;
    if (sub === 0) { // MFC1
      const buf = Buffer.alloc(4);
      buf.writeFloatLE(this.f[rt], 0);
      this.setReg(rt, buf.readInt32LE(0));
      return;
    } else if (sub === 4) { // MTC1
      const buf = Buffer.alloc(4);
      buf.writeInt32LE(this.r[rt] | 0, 0);
      this.f[rt] = buf.readFloatLE(0);
      this.d[rt] = this.f[rt];
      return;
    } else if (sub === 2) { // CFC1 - return FCSR for reg 31/0
      this.setReg(rt, this.fcsr);
      return;
    } else if (sub === 6) { // CTC1
      this.fcsr = this.r[rt];
      return;
    } else if (sub === 8) { // BC1
      const cc = (inst >> 18) & 0x7;
      const tf = (inst >> 16) & 0x1;
      const nd = (inst >> 16) & 0x1;
