      const target = (curPC + 4 + (((inst & 0xffff) & 0x8000) ? ((inst & 0xffff) | 0xffff0000) : (inst & 0xffff)) << 2) >>> 0;
      const delayPC = (curPC + 4) >>> 0;
      if (cond) { this.executeDelayAndJump(delayPC, target); return; }
      else return;
    } else {
      // Arithmetic
      const isSingle = (fmt === 0x10);
      const isDouble = (fmt === 0x11);
      const isWord = (fmt === 0x14);
      switch (funct) {
        case 0x00: // ADD.S/ADD.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] + this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] + this.d[ftReal];
          break;
        case 0x01: // SUB.S/SUB.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] - this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] - this.d[ftReal];
          break;
        case 0x02: // MUL.S/MUL.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] * this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] * this.d[ftReal];
          break;
        case 0x03: // DIV.S/DIV.D
          if (isSingle) this.f[fdReal] = this.f[fsReal] / this.f[ftReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal] / this.d[ftReal];
          break;
        case 0x04: // SQRT.S/SQRT.D
          if (isSingle) this.f[fdReal] = Math.sqrt(this.f[fsReal]);
          else if (isDouble) this.d[fdReal] = Math.sqrt(this.d[fsReal]);
          break;
        case 0x05: // ABS.S/ABS.D
          if (isSingle) this.f[fdReal] = Math.abs(this.f[fsReal]);
          else if (isDouble) this.d[fdReal] = Math.abs(this.d[fsReal]);
          break;
        case 0x06: // MOV.S/MOV.D
          if (isSingle) this.f[fdReal] = this.f[fsReal];
          else if (isDouble) this.d[fdReal] = this.d[fsReal];
          break;
        case 0x07: // NEG.S/NEG.D
          if (isSingle) this.f[fdReal] = -this.f[fsReal];
          else if (isDouble) this.d[fdReal] = -this.d[fsReal];
          break;
        case 0x08: { // ROUND.L.S etc - for word conversion
          if (isSingle) { const v = Math.round(this.f[fsReal]); this.d[fdReal] = v; }
          else if (isDouble) { const v = Math.round(this.d[fsReal]); this.d[fdReal] = v; }
          break;
        }
        case 0x09: { // TRUNC.L.S etc - for word: trunc.w.s
          if (isSingle) { const v = Math.trunc(this.f[fsReal]); this.f[fdReal] = v; }
          else if (isDouble) { const v = Math.trunc(this.d[fsReal]); this.d[fdReal] = v; }
          break;
        }
        case 0x12: { // MOVZ
          if ((this.r[rt] | 0) === 0) { if (isSingle) this.f[fdReal]=this.f[fsReal]; else this.d[fdReal]=this.d[fsReal]; }
          break;
        }
        case 0x13: { // MOVN
          if ((this.r[rt] | 0) !== 0) { if (isSingle) this.f[fdReal]=this.f[fsReal]; else this.d[fdReal]=this.d[fsReal]; }
          break;
        }
        case 0x20: { // CVT.S.D / CVT.S.W etc
          if (isWord) this.f[fdReal] = this.f[fsReal]; // already float? We need word in f as int rep
          else if (isDouble) this.f[fdReal] = this.d[fsReal];
        }
          break;
        case 0x21: { // CVT.D.S/W
          if (isSingle) this.d[fdReal] = this.f[fsReal];
          else if (isWord) {
            const buf = Buffer.alloc(4);
            buf.writeFloatLE(this.f[fsReal], 0);
            const wv = buf.readInt32LE(0);
            this.d[fdReal] = wv;
          }
          break;
        }
        case 0x24: { // CVT.W.S/D - convert to int32 stored as float bits
          if (isSingle) {
            const v = Math.trunc(this.f[fsReal]);
            const buf = Buffer.alloc(4);
            buf.writeInt32LE(v | 0, 0);
            this.f[fdReal] = buf.readFloatLE(0);
          } else if (isDouble) {
            const v = Math.trunc(this.d[fsReal]);
            const buf = Buffer.alloc(4);
            buf.writeInt32LE(v | 0, 0);
            this.f[fdReal] = buf.readFloatLE(0);
          }
          break;
        }
        case 0x32: { // C.EQ.S/D
          { if (isSingle) this.fcc[cc] = (this.f[fsReal] === this.f[ftReal]) ? 1 : 0;
            else this.fcc[cc] = (this.d[fsReal] === this.d[ftReal]) ? 1 : 0; }
          break;
        }
        case 0x33: { // C.LT.S/D
          { if (isSingle) this.fcc[cc] = (this.f[fsReal] < this.f[ftReal]) ? 1 : 0;
            else this.fcc[cc] = (this.d[fsReal] < this.d[ftReal]) ? 1 : 0; }
          break;
        }
        case 0x34: { // C.LE.S/D
          { if (isSingle) this.fcc[cc] = (this.f[fsReal] <= this.f[ftReal]) ? 1 : 0;
            else this.fcc[cc] = (this.d[fsReal] <= this.d[ftReal]) ? 1 : 0; }
          break;
        }
        case 0x3c: { // C.LT with false? (F) - skip
          break;
        }
        case 0x3d: { // C.NGE (F) - skip
          break;
        }
        case 0x3e: { // C.LE with false? - skip
          break;
        }
        default:
          this.halt(`unknown FPU funct 0x${funct.toString(16)} inst=0x${inst.toString(16)} pc=0x${curPC.toString(16)} fmt=0x${fmt.toString(16)}`);
          break;
      }
    }
  }

  halt(msg) {
    this.running = false;
    console.error(`[vm] HALT: ${msg} instCount=${this.instCount} pc=0x${this.pc.toString(16)}`);
    console.error('registers:', Array.from(this.r).map((v,i)=>`r${i}=${v>>>0}`));
  }
}

// ---------- ELF Loader ----------
function loadELF(mem, path) {
  const buf = fs.readFileSync(path);
  // 32-bit LE ELF
  const e_type = buf.readUInt16LE(16);
  const e_machine = buf.readUInt16LE(18);
  if (e_machine !== 8) throw new Error(`Not MIPS: e_machine=${e_machine}`);
  const e_entry = buf.readUInt32LE(24);
  const e_phoff = buf.readUInt32LE(28);
  const e_phentsize = buf.readUInt16LE(42);
  const e_phnum = buf.readUInt16LE(44);
  // also get .reginfo gp
  const e_shoff = buf.readUInt32LE(32);
  const e_shentsize = buf.readUInt16LE(46);
  const e_shnum = buf.readUInt16LE(48);
  const e_shstrndx = buf.readUInt16LE(50);
  let gpValue = 0;
  // Parse section headers to find .reginfo
  for (let i = 0; i < e_shnum; i++) {
    const off = e_shoff + i * e_shentsize;
    const sh_name = buf.readUInt32LE(off);
    const sh_type = buf.readUInt32LE(off + 4);
    const sh_addr = buf.readUInt32LE(off + 12);
    const sh_offset = buf.readUInt32LE(off + 16);
    const sh_size = buf.readUInt32LE(off + 20);
    if (sh_type === 0x7000000a && sh_size >= 24) { // .reginfo
      gpValue = buf.readUInt32LE(sh_offset + 20);
    }
  }
  // Load PT_LOAD segments
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(off);
    if (p_type !== 1) continue; // PT_LOAD
    const p_offset = buf.readUInt32LE(off + 4);
    const p_vaddr = buf.readUInt32LE(off + 8);
    const p_filesz = buf.readUInt32LE(off + 16);
    const p_memsz = buf.readUInt32LE(off + 20);
    const seg = buf.subarray(p_offset, p_offset + p_filesz);
    mem.copyFromBuffer(p_vaddr, seg);
    if (p_memsz > p_filesz) {
      mem.zeroRange(p_vaddr + p_filesz, p_memsz - p_filesz);
    }
  }
  return { entry: e_entry, gp: gpValue };
}

// ---------- Main ----------
function main() {
  const mem = new Memory();
  const { entry, gp } = loadELF(mem, ELF_PATH);
  const cpu = new CPU(mem);
  cpu.setPC(entry);
  cpu.r[28] = gp | 0; // $gp
  cpu.r[29] = 0x80000000 | 0; // $sp - high address outside BSS; BSS starts at 0x4750c0 size ~0x4003c6d0 -> ~0x447???
  // Actually BSS: 0x4750c0 + 0x4003c6d0 = 0x4480D190. So use sp=0x90000000.
  cpu.r[29] = 0x90000000 | 0;
  // Set up argc/argv on stack for main(0,0) via __start
  // __start calls main(0,0), so no need for argv. But stack should be valid.

  let lastProgress = Date.now();
  let lastInst = 0;
  const startTime = Date.now();

  // Run
  let checkInterval = 1000000;
  while (cpu.running) {
    cpu.step();
    if ((cpu.instCount & (checkInterval - 1)) === 0) {
      const now = Date.now();
      if (now - lastProgress > 5000) {
        const mips = ((cpu.instCount - lastInst) / 1000000).toFixed(2);
        console.error(`[vm] pc=0x${cpu.pc.toString(16)} inst=${cpu.instCount} ${mips}Mips ${((now-startTime)/1000).toFixed(1)}s`);
        lastProgress = now; lastInst = cpu.instCount;
      }
      // Check if /tmp/frame.bmp exists, but keep running for a while
      if (cpu.instCount > 50000000 && fs.existsSync('/tmp/frame.bmp')) {
        console.error('[vm] /tmp/frame.bmp exists, stopping after first frame');
        cpu.running = false;
      }
    }
    if (cpu.instCount > 1000000000) { console.error('[vm] instruction limit reached'); cpu.running = false; }
  }

  console.error(`[vm] exited code=${cpu.exitCode} instCount=${cpu.instCount}`);
}

